css:
/* Style for integer input fields */
[data-fieldtype="Int"] .value {
    text-align: left;
    padding: 4px;
    border: 2px solid #aaa; /* Thinner border */
    border-radius: 8px;
    background-color: #f9f9f9;
    font-family: 'Calibri', sans-serif;
    font-size: 14px;
    line-height: 1.0; /* Reduces the space between lines within the field */
    margin-bottom: 0px; /* Removes the gap between text elements */
    transition: border-color 0.3s ease;
}

[data-fieldtype="Int"] .value:focus {
    border-color: #4CAF50; /* Green color for focused fields */
    background-color: #e8f5e9;
    outline: none;
}

/* Style for section breaks */
.section-break {
    padding: 0px 0px; /* Further reduced padding for a tighter look */
    border-bottom: 0px solid #ddd; /* Thinner border */
    margin-bottom: 0px; /* Reduced margin between sections */
}

.section-break:last-child {
    padding-bottom: 0px;
    border-bottom: 2px;
    margin-bottom: 0;
}

/* Adding a subtle shadow to the sections */
.section-break {
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05); /* Light shadow for subtle depth */
}

/* Table styling */
table {
    width: 100%;
    border-collapse: collapse; /* Removes space between table cells */
    border-spacing: 0; /* Closes any gaps between rows */
}

table th, table td {
    padding: 2px 2px; /* Further reduced padding in table cells */
    text-align: left; /* Align text to the left */
    border: 1px solid #ddd; /* Light border for table cells */
    margin: 0; /* Ensures no extra margin between rows */
}

table th {
    background-color: #e0f2f1; /* Light green color for table header */
    color: #333; /* Darker text color for contrast */
    font-weight: bold;
}

table td {
    background-color: #f9f9f9; /* Light background for table cells */
}

/* Optional: Adding a hover effect for table rows */
table tr:hover {
    background-color: #f1f8e9; /* Light green background on hover */
}

html:
{%- set tc_html = doc.terms -%}
{%- if not tc_html and doc.tc_name -%}
  {%- set tc_html = frappe.db.get_value("Terms and Conditions", doc.tc_name, "terms") -%}
{%- endif -%}

<div class="sales-invoice">
    <!-- DYNAMIC HEADER WITH LOGO -->
    <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px;">
        <div>
            <h1 style="margin: 0 0 3px 0; font-size: 22px; color: #111;">SALES ORDER</h1>
            <div style="font-size: 12px; color: #666;">
                <strong>Invoice No:</strong> {{ doc.name }} | 
                <strong>Date:</strong> {{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}
            </div>
        </div>
        <div style="text-align: right;">
            <img src="/files/Plumes Logo.png" alt="Company Logo" style="height: 50px; margin-bottom: 3px;">
            <div style="font-size: 14px; font-weight: bold; color: #333;">
                {{ frappe.db.get_value("Company", doc.company, "company_name") or doc.company }}
            </div>
            <div style="font-size: 11px; color: #777; margin-top: 2px;">
                {% if doc.company_tax_id %}
                <strong>Tax ID:</strong> {{ doc.company_tax_id }}
                {% endif %}
            </div>
            <div style="font-size: 10px; color: #999; margin-top: 2px;">
                Printed: {{ frappe.utils.now_datetime().strftime("%d-%m-%Y %H:%M") }}
            </div>
        </div>
    </div>

    <!-- COMPACT INVOICE DETAILS -->
    <table style="width: 100%; margin: 6px 0; font-size: 12px; background: #f8f9fa; border-radius: 5px; padding: 6px;">
        <tr>
            <td width="33%"><strong>Customer:</strong> {{ doc.customer_name }}</td>
            <td width="33%"><strong>Due Date:</strong> {{ frappe.utils.formatdate(doc.due_date, "dd-MM-yyyy") if doc.due_date else "N/A" }}</td>
            <td width="34%" style="text-align: right;"><strong>Currency:</strong> {{ doc.currency }}</td>
        </tr>
    </table>

    <!-- CUSTOMER DETAILS ONLY -->
    <div style="border: 1px solid #ddd; border-radius: 5px; padding: 8px 12px; margin-bottom: 10px;">
        <table style="width: 100%; font-size: 12px;">
            <tr>
                <td style="width: 100px; vertical-align: top;"><strong>Address:</strong></td>
                <td>{{ doc.address_display or "" }}</td>
            </tr>
            {% if doc.tax_id %}
            <tr>
                <td><strong>Tax ID:</strong></td>
                <td>{{ doc.tax_id }}</td>
            </tr>
            {% endif %}
        </table>
    </div>

    <!-- ITEMS TABLE -->
    <div style="margin-bottom: 12px; page-break-inside: avoid;">
        <div style="font-weight: bold; font-size: 13px; color: #333; margin-bottom: 5px;">Items & Services</div>
        <table style="width: 100%; font-size: 11px; border-collapse: collapse; border: 1px solid #ddd;">
            <thead>
                <tr style="background: #e9ecef;">
                    <th style="text-align: left; padding: 6px 8px; border: 1px solid #ccc; font-weight: bold;">#</th>
                    <th style="text-align: left; padding: 6px 8px; border: 1px solid #ccc; font-weight: bold;">Item Code</th>
                    <th style="text-align: left; padding: 6px 8px; border: 1px solid #ccc; font-weight: bold;">Description</th>
                    <th style="text-align: center; padding: 6px 8px; border: 1px solid #ccc; font-weight: bold;">Qty</th>
                    <th style="text-align: center; padding: 6px 8px; border: 1px solid #ccc; font-weight: bold;">UOM</th>
                    <th style="text-align: right; padding: 6px 8px; border: 1px solid #ccc; font-weight: bold;">Rate</th>
                    <th style="text-align: right; padding: 6px 8px; border: 1px solid #ccc; font-weight: bold;">Amount</th>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.items %}
                <tr>
                    <td style="padding: 6px 8px; border: 1px solid #eee; text-align: center;">{{ loop.index }}</td>
                    <td style="padding: 6px 8px; border: 1px solid #eee;">{{ item.item_code }}</td>
                    <td style="padding: 6px 8px; border: 1px solid #eee;">{{ item.item_name or item.description }}{% if item.batch_no %} <span style="color: #555;">| Batch: {{ item.batch_no }}</span>{% endif %}</td>
                    <td style="padding: 6px 8px; border: 1px solid #eee; text-align: center;">{{ item.qty }}</td>
                    <td style="padding: 6px 8px; border: 1px solid #eee; text-align: center;">{{ item.uom }}</td>
                    <td style="padding: 6px 8px; border: 1px solid #eee; text-align: right;">{{ frappe.format_value(item.rate, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
                    <td style="padding: 6px 8px; border: 1px solid #eee; text-align: right;">{{ frappe.format_value(item.amount, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>

    <!-- TERMS (left)  |  TAX CALCULATION + AMOUNT IN WORDS (right) -->
    <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px; page-break-inside: avoid;">
        <tr>
            <!-- TERMS (from tc_name) -->
            <td style="width: 55%; vertical-align: top; padding-right: 15px; font-size: 11px; line-height: 1.5;">
                <div class="terms">{{ tc_html or "" }}</div>
            </td>

            <!-- RIGHT COLUMN -->
            <td style="width: 45%; vertical-align: top;">
                <!-- TAX CALCULATION -->
                <div style="border: 1px solid #ddd; border-radius: 5px; padding: 8px 10px;">
                    <div style="font-weight: bold; font-size: 13px; color: #333; margin-bottom: 5px;">Tax Calculation</div>
                    <table style="width: 100%; font-size: 12px;">
                        <tr>
                            <td><strong>Net Total:</strong></td>
                            <td style="text-align: right;">{{ frappe.format_value(doc.net_total, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
                        </tr>
                        {% for tax in doc.taxes %}
                        <tr>
                            <td>{{ tax.account_head }} ({{ tax.rate }}%):</td>
                            <td style="text-align: right;">+ {{ frappe.format_value(tax.tax_amount, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
                        </tr>
                        {% endfor %}
                        {% if doc.discount_amount %}
                        <tr>
                            <td><strong>Discount:</strong></td>
                            <td style="text-align: right; color: #c62828;">- {{ frappe.format_value(doc.discount_amount, {'fieldtype': 'Currency', 'options': doc.currency}) }}</td>
                        </tr>
                        {% endif %}
                        <tr style="border-top: 1px solid #ccc;">
                            <td style="padding-top: 5px;"><strong>Grand Total:</strong></td>
                            <td style="text-align: right; padding-top: 5px; font-weight: bold; font-size: 14px; color: #2e7d32;">
                                {{ frappe.format_value(doc.grand_total, {'fieldtype': 'Currency', 'options': doc.currency}) }}
                            </td>
                        </tr>
                    </table>
                </div>

                <!-- AMOUNT IN WORDS (compact) -->
                <div style="border: 1px solid #cce0ff; border-radius: 5px; padding: 6px 10px; background: #f0f7ff; margin-top: 8px;">
                    <div style="font-weight: bold; font-size: 11px; color: #333; margin-bottom: 3px;">Amount in Words</div>
                    <div style="font-size: 11px; line-height: 1.3;">
                        {{ doc.in_words or "Not specified" }}
                    </div>
                </div>
            </td>
        </tr>
    </table>

    <!-- SIGNATURE -->
    <div style="margin-top: 20px; page-break-inside: avoid;">
        <div style="display: flex; gap: 40px; justify-content: space-between;">
            <div style="flex: 1; text-align: center; font-size: 11px;">
                <div style="border-top: 1px solid #444; margin-bottom: 8px; padding-top: 20px;"></div>
                <strong>Prepared By</strong><br>
                <span style="color: #666;">Sign & Date</span>
            </div>
            <div style="flex: 1; text-align: center; font-size: 11px;">
                <div style="border-top: 1px solid #444; margin-bottom: 8px; padding-top: 20px;"></div>
                <strong>Received By</strong><br>
                <span style="color: #666;">Sign & Date</span>
            </div>
        </div>
    </div>

    <!-- FOOTER NOTE -->
    <div style="border-top: 1px solid #ccc; margin-top: 15px; padding-top: 6px; text-align: center; color: #666; font-size: 10px;">
        <p style="margin: 2px 0; font-style: italic;">Invoice: {{ doc.name }} | Company: {{ doc.company }} | Printed on: {{ frappe.utils.now_datetime().strftime("%d-%m-%Y %H:%M") }}</p>
    </div>
</div>

<style>
.sales-invoice {
    font-family: "Segoe UI", Arial, sans-serif;
    color: #222;
    line-height: 1.4;
    font-size: 12px;
    max-width: 800px;
    margin: 0 auto;
    padding: 0;
}

.sales-invoice .terms p,
.sales-invoice .terms div { margin: 0; }

/* PRINT STYLES */
@media print {
    .sales-invoice {
        max-width: 100%;
        padding: 0;
        margin: 0;
    }

    @page {
        size: A4 portrait;
        margin: 12.7mm 15mm 15mm 15mm; /* top = 0.5 inch */
    }

    @page :first {
        margin-top: 12.7mm;
    }

    .page-break { page-break-before: always; }

    h1, h2, h3, h4 { page-break-after: avoid; }

    body, html { height: auto; overflow: visible; }

    .sales-invoice { height: auto; min-height: 100%; }

    * {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    .no-print { display: none !important; }

    thead { display: table-header-group; }
    tfoot { display: table-footer-group; }

    table { page-break-inside: auto; }

    tr {
        page-break-inside: avoid;
        page-break-after: auto;
    }
}

@media screen and (max-width: 768px) {
    .sales-invoice {
        font-size: 11px;
        padding: 10px;
    }
}
</style>
